import{_ as c,r as t,o as i,c as r,e as o,a,s as e,d as n}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Pagination - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Basic usage","slug":"basic-usage","link":"#basic-usage","children":[{"level":3,"title":"Paginating Query Builder Results","slug":"paginating-query-builder-results","link":"#paginating-query-builder-results","children":[{"level":4,"title":"Simple Pagination","slug":"simple-pagination","link":"#simple-pagination","children":[]},{"level":4,"title":"Specify a Page Number","slug":"specify-a-page-number","link":"#specify-a-page-number","children":[]},{"level":4,"title":"Specify a Custom Query Name","slug":"specify-a-custom-query-name","link":"#specify-a-custom-query-name","children":[]}]},{"level":3,"title":"Paginating Model Results","slug":"paginating-model-results","link":"#paginating-model-results","children":[]},{"level":3,"title":"Manually Creating a Paginator","slug":"manually-creating-a-paginator","link":"#manually-creating-a-paginator","children":[]}]},{"level":2,"title":"Displaying Results in a View","slug":"displaying-results-in-a-view","link":"#displaying-results-in-a-view","children":[{"level":4,"title":"Customizing the Paginator URI","slug":"customizing-the-paginator-uri","link":"#customizing-the-paginator-uri","children":[]},{"level":4,"title":"Appending to Pagination Links","slug":"appending-to-pagination-links","link":"#appending-to-pagination-links","children":[]},{"level":4,"title":"Additional Helper Methods","slug":"additional-helper-methods","link":"#additional-helper-methods","children":[]}]},{"level":2,"title":"Converting results to JSON","slug":"converting-results-to-json","link":"#converting-results-to-json","children":[{"level":4,"title":"Example Paginator JSON","slug":"example-paginator-json","link":"#example-paginator-json","children":[]},{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/database/pagination.md","filePath":"4.x/extend/database/pagination.md"}'),u={name:"4.x/extend/database/pagination.md"};function g(d,s,k,h,m,f){const p=t("pre-heading"),l=t("post-heading");return i(),r("div",null,[o(p),s[0]||(s[0]=a("h1",null,"Pagination",-1)),o(l),s[1]||(s[1]=e(`<h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic usage</h2><p>There are a few ways to paginate records, the most common is to call the <code>paginate</code> method on a query or model. This will return a special paginated collection that adds extra methods for displaying the results.</p><h3 id="paginating-query-builder-results"><a href="#paginating-query-builder-results" class="header-anchor">#</a> Paginating Query Builder Results</h3><p>There are several ways to paginate items. The simplest is by using the <code>paginate</code> method on the <a href="./query.html">query builder</a> or a <a href="./model.html">model query</a>. The <code>paginate</code> method automatically takes care of setting the proper limit and offset based on the current page being viewed by the user. By default, the current page is detected by the value of the <code>?page</code> query string argument on the HTTP request. Of course, this value is automatically detected and automatically inserted into links generated by the paginator.</p><p>First, let&#39;s take a look at calling the <code>paginate</code> method on a query. In this example, the only argument passed to <code>paginate</code> is the number of items you would like displayed &quot;per page&quot;. In this case, let&#39;s specify that we would like to display <code>15</code> items per page.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Currently, pagination operations that use a <code>groupBy</code> statement cannot be executed efficiently. If you need to use a <code>groupBy</code> with a paginated result set, it is recommended that you query the database and create a paginator manually.</p></div><h4 id="simple-pagination"><a href="#simple-pagination" class="header-anchor">#</a> Simple Pagination</h4><p>If you only need to display simple &quot;Next&quot; and &quot;Previous&quot; links in your pagination view, you have the option of using the <code>simplePaginate</code> method to perform a more efficient query. This is very useful for large datasets if you do not need to display a link for each page number when rendering your view.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="specify-a-page-number"><a href="#specify-a-page-number" class="header-anchor">#</a> Specify a Page Number</h4><p>By default the paginator will take the current page number from the <code>?page</code> query string. You can specify a page number with the <code>paginateAtPage</code> and <code>simplePaginateAtPage</code> methods. The number of pages are supplied (first argument) along with the current page number (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$recordsPerPage</span> <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span>
<span class="token variable">$currentPage</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginateAtPage</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token variable">$currentPage</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginateAtPage</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token variable">$currentPage</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="specify-a-custom-query-name"><a href="#specify-a-custom-query-name" class="header-anchor">#</a> Specify a Custom Query Name</h4><p>The <code>paginateCustom</code> and <code>simplePaginateCustom</code> methods are used for a custom query string name. The following will use the <code>?secondPage</code> query string to determine the page number.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$recordsPerPage</span> <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginateCustom</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;secondPage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginateCustom</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;secondPage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="paginating-model-results"><a href="#paginating-model-results" class="header-anchor">#</a> Paginating Model Results</h3><p>You may also paginate <a href="./model.html">database model</a> queries. In this example, we will paginate the <code>User</code> model with <code>15</code> items per page. As you can see, the syntax is nearly identical to paginating query builder results:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Of course, you may call <code>paginate</code> after setting other constraints on the query, such as <code>where</code> clauses:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also use the <code>simplePaginate</code> method when paginating models:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may specify the page number manually by passing a second argument, here we paginate <code>15</code> items per page, specifying that we are on page <code>2</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="manually-creating-a-paginator"><a href="#manually-creating-a-paginator" class="header-anchor">#</a> Manually Creating a Paginator</h3><p>Sometimes you may wish to create a pagination instance manually, passing it an array of items. You may do so by creating either an <code>Illuminate\\Pagination\\Paginator</code> or <code>Illuminate\\Pagination\\LengthAwarePaginator</code> instance, depending on your needs.</p><p>The <code>Paginator</code> class does not need to know the total number of items in the result set, because of this the class does not have methods for retrieving the index of the last page. The <code>LengthAwarePaginator</code> accepts almost the same arguments as the <code>Paginator</code>, however it does require a count of the total number of items in the result set.</p><p>In other words, the <code>Paginator</code> corresponds to the <code>simplePaginate</code> method on the query builder and models, while the <code>LengthAwarePaginator</code> corresponds to the <code>paginate</code> method.</p>`,29)),s[2]||(s[2]=a("p",null,[n(`When manually creating a paginator instance, you should manually "slice" the array of results you pass to the paginator. If you're unsure how to do this, check out the `),a("a",{href:"http://php.net/manual/en/function.array-slice.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("array_slice"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),a("span",{class:"sr-only"},"(opens new window)")])]),n(" PHP function.")],-1)),s[3]||(s[3]=e(`<h2 id="displaying-results-in-a-view"><a href="#displaying-results-in-a-view" class="header-anchor">#</a> Displaying Results in a View</h2><p>When you call the <code>paginate</code> or <code>simplePaginate</code> methods on a query builder or model query, you will receive a paginator instance. When calling the <code>paginate</code> method, you will receive an instance of <code>Illuminate\\Pagination\\LengthAwarePaginator</code>. When calling the <code>simplePaginate</code> method, you will receive an instance of <code>Illuminate\\Pagination\\Paginator</code>. These objects provide several methods that describe the result set. In addition to these helpers methods, the paginator instances are iterators and may be looped as an array.</p><p>So once you have retrieved the results, you may display the results and render the page links using PHP or <a href="./../../markup/function/pager.html">the Twig Pager function</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endforeach</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">links</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,4)),s[4]||(s[4]=a("p",null,[n("The "),a("code",null,"render"),n(" method will render the links to the rest of the pages in the result set. Each of these links will already contain the proper "),a("code",null,"?page"),n(" query string variable. The HTML generated by the "),a("code",null,"render"),n(" method is compatible with the "),a("a",{href:"https://getbootstrap.com",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Bootstrap CSS framework"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),a("span",{class:"sr-only"},"(opens new window)")])]),n(".")],-1)),s[5]||(s[5]=e(`<div class="custom-block tip"><p>When calling the <code>render</code> method from a Twig template, be sure to use the <code>|raw</code> filter so the HTML links are not escaped.</p></div><h4 id="customizing-the-paginator-uri"><a href="#customizing-the-paginator-uri" class="header-anchor">#</a> Customizing the Paginator URI</h4><p>The <code>setPath</code> method allows you to customize the URI used by the paginator when generating links. For example, if you want the paginator to generate links like <code>http://example.tld/custom/url?page=N</code>, you should pass <code>custom/url</code> to the <code>setPath</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">setPath</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;custom/url&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="appending-to-pagination-links"><a href="#appending-to-pagination-links" class="header-anchor">#</a> Appending to Pagination Links</h4><p>You may add to the query string of pagination links using the <code>appends</code> method. For example, to append <code>&amp;sort=votes</code> to each pagination link, you should make the following call to <code>appends</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">appends</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sort&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you wish to append a &quot;hash fragment&quot; to the paginator&#39;s URLs, you may use the <code>fragment</code> method. For example, to append <code>#foo</code> to the end of each pagination link, make the following call to the <code>fragment</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fragment</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="additional-helper-methods"><a href="#additional-helper-methods" class="header-anchor">#</a> Additional Helper Methods</h4><p>You may also access additional pagination information via the following methods on paginator instances:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">currentPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">hasMorePages</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">lastPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// Not available when using simplePaginate</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">nextPageUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">perPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">previousPageUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">total</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// Not available when using simplePaginate</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="converting-results-to-json"><a href="#converting-results-to-json" class="header-anchor">#</a> Converting results to JSON</h2><p>The paginator result classes implement the <code>Illuminate\\Contracts\\Support\\JsonableInterface</code> contract and expose the <code>toJson</code> method, so it&#39;s very easy to convert your pagination results to JSON. You may also convert a paginator instance to JSON by simply returning it from a route or AJAX handler:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The JSON from the paginator will include meta information such as <code>total</code>, <code>current_page</code>, <code>last_page</code>, and more. The actual result objects will be available via the <code>data</code> key in the JSON array. Here is an example of the JSON created by returning a paginator instance from a route:</p><h4 id="example-paginator-json"><a href="#example-paginator-json" class="header-anchor">#</a> Example Paginator JSON</h4><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;total&quot;</span><span class="token operator">:</span> <span class="token number">50</span><span class="token punctuation">,</span>
    <span class="token property">&quot;per_page&quot;</span><span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">,</span>
    <span class="token property">&quot;current_page&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;last_page&quot;</span><span class="token operator">:</span> <span class="token number">4</span><span class="token punctuation">,</span>
    <span class="token property">&quot;next_page_url&quot;</span><span class="token operator">:</span> <span class="token string">&quot;http://octobercms.app?page=2&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;prev_page_url&quot;</span><span class="token operator">:</span> <span class="token null keyword">null</span><span class="token punctuation">,</span>
    <span class="token property">&quot;from&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;to&quot;</span><span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">,</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span><span class="token punctuation">[</span>
        <span class="token punctuation">{</span>
            <span class="token comment">// Result Object</span>
        <span class="token punctuation">}</span><span class="token punctuation">,</span>
        <span class="token punctuation">{</span>
            <span class="token comment">// Result Object</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../ajax/features/pagination.html">CMS Pagination</a></li><li><a href="./../../markup/function/pager.html">Pager Twig function</a></li></ul></div>`,20))])}const b=c(u,[["render",g]]);export{v as __pageData,b as default};
